  put("m2_addth", "三角関数の合成", "fig", '<svg viewBox="0 0 220 154" class="lz-fig" role="img" aria-label="点(a, b)をとり、原点からの距離rとx軸とのなす角αを読むと a sinθ + b cosθ = r sin(θ+α)"><line x1="8" y1="112" x2="96" y2="112" class="ax"/><path d="M90 115.3 L96 112 L90 108.7" class="ax"/><line x1="28" y1="128" x2="28" y2="8" class="ax"/><path d="M31.3 14 L28 8 L24.7 14" class="ax"/><line x1="78" y1="25.4" x2="78" y2="112" class="dash"/><line x1="78" y1="25.4" x2="28" y2="25.4" class="dash"/><line x1="28" y1="112" x2="78" y2="25.4" class="cv2"/><path d="M77.8 33.4 L78 25.4 L71.2 29.5" class="cv2"/><path d="M46 112 A18 18 0 0 0 37 96.4" class="arc"/><circle cx="78" cy="25.4" r="3.5" class="pt"/><text x="78" y="126" text-anchor="middle">a</text><text x="16" y="29.4">b</text><text x="84" y="23.4">(a, b)</text><text x="40" y="62">r</text><text x="48" y="106">α</text><text x="102" y="62">a sinθ + b cosθ</text><text x="102" y="80">= r sin(θ + α)</text><text x="102" y="98">r = √(a² + b²)</text><text x="110" y="146" text-anchor="middle">例:点 (1, √3) → r = 2、α = π/3</text></svg>');
